          "explanation": "「약사법」 제8장 보칙에 따르면 해답을 찾을 수 있다.\n① 제86조의4 1항에 따르면 피해구제급여를 받으려는 사람은 총리령으로\n정하는 바에 따라 서류를 첨부하여 의약품안전관리원의 장에게 피해구제급\n여의 지급을 신청하여야 한다.\n② 제86조의3 2항 3호에 따라 옳다.\n③ 제86조의3 2항 1호에 따라 암이나 그 밖의 특수질병에 사용되는 의약품\n으로 식품의약품안전처장이 정하는 의약품인 경우 피해구제급여를 지급하\n지 아니한다.\n④ 제86조의2 2항에 따라 피해구제를 위하여 의약품의 제조업자ㆍ품목허\n가를 받은 자 및 수입자로부터 의약품 부작용 피해구제 부담금(이하 “부담\n금”이라 한다)을 부과ㆍ징수한다.\n부담금은 이 법에 따라 전문의약품 또는 일반의약품으로 분류되는 의약품\n의 생산액 또는 수입액에 비례하여 부과하는 기본부담금과 심의위원회의\n심의를 거쳐 식품의약품안전처장이 부작용 피해구제의 필요성을 인정한 의\n약품으로 판정된 의약품에 부과하는 추가부담금으로 하되, 다음 각 호의 금\n액을 초과하지 아니하는 범위에서 대통령령으로 정하는 금액으로 한다.\n1. 기본부담금: 전년도 의약품 생산액 및 수입액의 1000분의 1\n2. 추가부담금: 전년도 해당 의약품으로 인한 피해구제 지급액의 100분의\n25. 다만, 그 의약품의 전년도 생산액ㆍ수입액의 100분의 1을 초과하지 아\n니한다.\n⑤ 제86조의3 2항 2호에 따라 의약품 부작용으로 인한 질병, 장애 또는 사\n망이 「감염병의 예방 및 관리에 관한 법률」에 따른 예방접종으로 인한 것\n인 경우 피해구제급여를 지급하지 아니한다.\n\n[[PAGE 11]]\nⅧ. 제8장 보칙\n가톨릭대 약학대학\n2025.04"
