          "explanation": "「약사법」 제8장 보칙에 따르면 해답을 찾을 수 있다.\n① 제85조 4항에 따라 「수의사법」에 따른 동물병원 개설자는 제44조에도\n불구하고 동물 사육자에게 동물용 의약품을 판매하거나, 동물을 진료할 목\n적으로 제50조제2항 단서에 따라 약국개설자로부터 의약품을 구입할 수\n있다. 이 경우 동물병원 개설자는 농림축산식품부령 또는 해양수산부령으로\n정하는 바에 따라 거래 현황을 작성ㆍ보존하여야 한다.\n② 제85조 7항에 따라 주사용 항생물질 제제와 주사용 생물학적 제제는\n수의사 또는 수산질병관리사의 처방전 없이 판매할 수 없다.\n③, ④ 제85조 8항에 따라 다음 각 호의 어느 하나에 해당하면 동물용 의\n약품을 수의사 또는 수산질병관리사의 처방전 없이 판매할 수 있다\n1. 농림축산식품부장관 또는 해양수산부장관이 정하는 도서ㆍ벽지의 축산농\n가 또는 수산생물양식어가에 판매하는 경우\n2. 농림축산식품부장관 또는 해양수산부장관, 시ㆍ도지사 또는 시장ㆍ군수\nㆍ구청장이 긴급방역의 목적으로 「가축전염병예방법」 제15조 또는 「수산\n생물질병 관리법」 제13조에 따라 동물용 의약품의 사용을 명령한 경우\n⑤ 제85조 6항에 따라 동물용 의약품 도매상의 허가를 받은 자는 농림축\n산식품부장관 또는 해양수산부장관이 정하여 고시하는 다음 각 호의 어느\n하나에 해당하는 동물용 의약품을 수의사 또는 수산질병관리사의 처방전\n없이 판매하여서는 아니 된다\n1. 오용ㆍ남용으로 사람 및 동물의 건강에 위해를 끼칠 우려가 있는 동물용\n의약품\n2. 수의사 또는 수산질병관리사의 전문지식을 필요로 하는 동물용 의약품\n3. 제형과 약리작용상 장애를 일으킬 우려가 있다고 인정되는 동물용 의약\n품\n9\n9\n9\n0\n9\n\n[[PAGE 12]]\n가톨릭대 약학대학\n2025.06\n\n마약류 관리에 관한 법률\n기말\n\n가톨릭대 모음\n\n[[PAGE 13]]\nⅠ. 제1장 총칙\n가톨릭대 약학대학\n2025.06"
