          "explanation": "해설\n강도시험(Hardness Test)은 정제에 수직방향으로 압력을 가하여 파괴될 때의 힘을 측정하는 시험이다.\n반면 마손도시험은 회전에 의한 마모 정도를 평가한다.\n\n암기포인트\n강도시험 → 수직압력\n마손도시험 → 마모율"
