          "explanation": "▶ 정답: ① ㄱ, ㄴ, ㄷ, ㄹ, ㅁ (ㅂ: Bedaquiline의 작용기전은 결핵균의 'ATP synthase 억제'이며, mycolic acid 합성 억제는 아님 / Delamanid가 mycolic acid 합성 억제) ▌ Bedaquiline, Fluoroquinolone계 및 Linezolid (결핵 2차)"
